class CPUProfileHandle {
  #worker = null;
  #id = null;
  #promise = null;

  constructor(worker, id) {
    this.#worker = worker;
    this.#id = id;
  }

  stop() {
    if (this.#promise) {
      return this.#promise;
    }
    const stopTaker = this.#worker[kHandle]?.stopCpuProfile(this.#id);
    return this.#promise = new Promise((resolve, reject) => {
      if (!stopTaker) return reject(new ERR_WORKER_NOT_RUNNING());
      stopTaker.ondone = (err, profile) => {
        if (err) {
          return reject(err);
        }
        resolve(profile);
      };
    });
  };

  async [SymbolAsyncDispose]() {
    await this.stop();
  }
}

class HeapProfileHandle {
  #worker = null;
  #promise = null;

  constructor(worker) {
    this.#worker = worker;
