  stop() {
    if (this.#promise) {
      return this.#promise;
    }
    const stopTaker = this.#worker[kHandle]?.stopHeapProfile();
    return this.#promise = new Promise((resolve, reject) => {
      if (!stopTaker) return reject(new ERR_WORKER_NOT_RUNNING());
      stopTaker.ondone = (err, profile) => {
